            if (this_flag == 1) std::cout << " ***";
            std::cout << std::endl;
            flag |= this_flag;
        }
    }
    ss_a.close();

    std::cout << "Level: " << level << std::endl;

    // Done:
    if (flag == 0)
        std::cout << std::endl << "--- PASSED ---" << std::endl;
    else
        std::cout << std::endl << "*** FAILED ***" << std::endl;
    return (flag);
}
